namespace sv_5d05d1029531470e898c14d5b981d70a.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the selection changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A — Main Distribution" },
        new() { Id = "WH-B", Name = "Warehouse B — East Coast" },
        new() { Id = "WH-C", Name = "Warehouse C — West Coast" },
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_5d05d1029531470e898c14d5b981d70a.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts for a warehouse.
/// Supports polling with cross-component notification — when any component triggers
/// a refresh, ALL subscribers are notified via OnAlertCountChanged.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastAlertCount;

    public int LastAlertCount => _lastAlertCount;

    /// <summary>
    /// Fired whenever a new alert count is fetched. Subscribers must wrap
    /// StateHasChanged in InvokeAsync because this may fire from a timer thread.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query that returns items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches a fresh count and notifies ALL subscribers. Called by the polling
    /// component, but every subscribed component (sidebar badge, dashboard, etc.)
    /// receives the update.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        _lastAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnAlertCountChanged = null;
    }
}

