@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h2>📦 Warehouse Dashboard</h2>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.LastAlertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LastAlertCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.LastAlertCount
                </p>
                <p class="text-muted">items below minimum levels</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private WarehouseState WarehouseState { get; set; } = default!;
    [Inject] private InventoryAlertService AlertService { get; set; } = default!;

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        // Re-render when warehouse changes or alerts update
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            // Warehouse changed — fetch fresh data immediately
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
        });
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling when page becomes visible
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / navigation away
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

